public final class HttpRequest {
    private final String url;
    private final String method;
    private final Map<String, String> headers;
    private final byte[] body;
    private final Duration timeout;

    private HttpRequest(Builder builder) {
        this.url = builder.url;
        this.method = builder.method;
        this.headers = Collections.unmodifiableMap(new HashMap<>(builder.headers));
        this.body = builder.body != null ? builder.body.clone() : null;
        this.timeout = builder.timeout;
    }

    public static Builder newBuilder() { return new Builder(); }

    public String getUrl() { return url; }
    public String getMethod() { return method; }
    public Map<String, String> getHeaders() { return headers; }

    public static final class Builder {
        private String url;
        private String method = "GET";
        private final Map<String, String> headers = new HashMap<>();
        private byte[] body;
        private Duration timeout = Duration.ofSeconds(30);

        private Builder() {}

        public Builder url(String url) {
            this.url = Objects.requireNonNull(url, "URL cannot be null");
            return this;
        }

        public Builder method(String method) {
            this.method = Objects.requireNonNull(method, "HTTP method cannot be null").toUpperCase();
            return this;
        }

        public Builder header(String name, String value) {
            this.headers.put(name, value);
            return this;
        }

        public Builder timeout(Duration timeout) {
            this.timeout = Objects.requireNonNull(timeout, "Timeout cannot be null");
            return this;
        }

        public HttpRequest build() {
            // Atomic Invariant Validation
            if (url == null || url.isBlank()) {
                throw new IllegalStateException("Cannot construct HttpRequest without a valid URL");
            }
            if ("POST".equals(method) && (body == null || body.length == 0)) {
                // Warning or policy enforcement
            }
            return new HttpRequest(this);
        }
    }
}
